targets.query:
from(bucket: "metrics")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "locust_requests" and
    r._field == "status_code" and
    r.name =~ /^ur/
  )
  |> group()
  |> reduce(
    identity: {all: 0, success: 0},
    fn: (r, accumulator) => ({
      all: accumulator.all + 1,
      success: accumulator.success + (if r._value < 400 then 1 else 0)
    })
  )
  |> map(fn: (r) => ({
    _time: now(),
    _measurement: "locust_requests",
    _field: "success_rate",
    _value: if r.all == 0 then 0.0 else float(v: r.success) / float(v: r.all)
  }))

from(bucket: "metrics")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "locust_requests" and
    r._field == "status_code" and
    r.name =~ /^ur/
  )
  |> group()
  |> reduce(
    identity: {all: 0, success: 0},
    fn: (r, accumulator) => ({
      all: accumulator.all + 1,
      success: accumulator.success + (if r._value >= 400 then 1 else 0)
    })
  )
  |> map(fn: (r) => ({
    _time: now(),
    _measurement: "locust_requests",
    _field: "success_rate",
    _value: if r.all == 0 then 0.0 else float(v: r.success) / float(v: r.all)
  }))

from(bucket: "metrics")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "locust_requests" and
    r._field == "status_code" and
    r.name =~ /^uc/
  )
  |> group(columns: ["name"])
  |> reduce(
    identity: {all: 0, err: 0},
    fn: (r, accumulator) => ({
      all: accumulator.all + 1,
      err: accumulator.err + (if r._value >= 400 then 1 else 0)
    })
  )
  |> map(fn: (r) => ({
    transaction: r.name,
    success_count: r.all - r.err,
    error_count: r.err,
    error_percent: if r.all == 0 then 0.0 else float(v: r.err) / float(v: r.all)
  }))
  |> keep(columns: ["transaction", "success_count", "error_count", "error_percent"])
  |> yield(name: "requests_summary")

from(bucket: "metrics")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "locust_requests" and r["_field"] == "response_time_ms" and r.name =~ /^uc/)
  |> group(columns: ["name"])
  |> aggregateWindow(
      every: 30s,
      fn: (tables=<-, column) => tables |> quantile(q: 0.99, method: "estimate_tdigest"),
      createEmpty: false
  )
  |> yield(name: "p99_30s")

